15. 
16. import React from 'react';
17. import { css } from '@emotion/core';
18. import { Theme } from '@sumup/design-tokens';
19. 
20. import styled, { NoTheme, StyleProps } from '../../styles/styled';
21. 
22. import Title from './components/Title';
23. 
24. export interface HeaderProps {
25.   /**
26.    * The page title for the Header.
27.    */
28.   'title': string;
29.   /**
30.    * If the Header should appear only on
31.    * mobile screens (useful for when using together with the Sidebar).
32.    */
33.   'mobileOnly'?: boolean;
34.   /**
35.    * The child component of Header.
36.    */
37.   'children'?: React.ReactNode;
38. 
39.   'data-testid'?: string;
40. }
41. 
42. interface MobileOnlyProps extends StyleProps {
43.   theme: Theme;
44.   mobileOnly: boolean;
45. }
46. 
47. const containerStyles = ({ theme }: StyleProps) => css`
48.   label: header;
49.   width: 100%;
50.   display: flex;
51.   align-items: center;
52.   min-height: 64px;
53.   background-color: ${theme.colors.n900};
54.   padding: ${theme.spacings.mega};
55.   z-index: ${theme.zIndex.header};
56.   position: sticky;
57. `;
58. 
59. const mobileOnlyStyles = ({ theme, mobileOnly }: MobileOnlyProps) =>
60.   mobileOnly &&
61.   css`
62.     ${theme.mq.giga} {
63.       display: none;
64.     }
65.   `;
66. 
67. const Container = styled('div')<NoTheme>(mobileOnlyStyles && containerStyles);
68. 
69. export const Header = ({
70.   title,
71.   mobileOnly,
72.   children,
